<?php if ( ! defined( 'ABSPATH' ) ) { exit; } get_header(); while(have_posts()): the_post(); $apply_url=get_post_meta(get_the_ID(),'_nvconsult_apply_url',true); $employer=get_post_meta(get_the_ID(),'_nvconsult_employer',true); $requirements=get_post_meta(get_the_ID(),'_nvconsult_requirements',true); $benefits=get_post_meta(get_the_ID(),'_nvconsult_benefits',true); $location=get_post_meta(get_the_ID(),'_nvconsult_location',true); $related_jobs=new WP_Query(array('post_type'=>'nvconsult_job','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>array(get_the_ID()),'orderby'=>'date','order'=>'DESC')); ?>
<main class="single-shell"><section class="single-hero"><h1><?php the_title(); ?></h1><p class="entry-meta"><?php echo esc_html( $location ); ?></p><a class="btn-primary" href="<?php echo esc_url( $apply_url ? $apply_url : '#' ); ?>"><?php esc_html_e( 'Apply Now', 'nvconsult-theme-v2' ); ?></a></section><div class="single-layout"><div><div class="content-card"><?php the_content(); ?></div><section class="section" style="padding-top:32px;"><div class="related-grid"><div class="content-card"><h3><?php esc_html_e( 'Requirements', 'nvconsult-theme-v2' ); ?></h3><p><?php echo esc_html( $requirements ); ?></p></div><div class="content-card"><h3><?php esc_html_e( 'Benefits', 'nvconsult-theme-v2' ); ?></h3><p><?php echo esc_html( $benefits ); ?></p></div><div class="content-card"><h3><?php esc_html_e( 'Employer', 'nvconsult-theme-v2' ); ?></h3><p><?php echo esc_html( $employer ); ?></p></div></div></section><section class="section" style="padding-top:0;"><h2><?php esc_html_e( 'Related Jobs', 'nvconsult-theme-v2' ); ?></h2><div class="related-grid"><?php if($related_jobs->have_posts()): while($related_jobs->have_posts()): $related_jobs->the_post(); ?><article class="related-card content-card"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3></article><?php endwhile; wp_reset_postdata(); endif; ?></div></section></div><aside class="single-sidebar content-card"><p><strong><?php esc_html_e( 'Salary Range:', 'nvconsult-theme-v2' ); ?></strong> <?php echo esc_html( get_post_meta( get_the_ID(), '_nvconsult_salary_range', true ) ); ?></p><p><strong><?php esc_html_e( 'Accommodation:', 'nvconsult-theme-v2' ); ?></strong> <?php echo esc_html( get_post_meta( get_the_ID(), '_nvconsult_accommodation', true ) ); ?></p><p><strong><?php esc_html_e( 'Closing Date:', 'nvconsult-theme-v2' ); ?></strong> <?php echo esc_html( get_post_meta( get_the_ID(), '_nvconsult_closing_date', true ) ); ?></p></aside></div></main>
